import numpy as np
import pandas.core.nanops as nanops

def nanflag(x):
    try:
        return bool(np.isnan(x))
    except (TypeError, ValueError):
        return False

ops = ["nanvar", "nanstd", "nansem"]
dtypes = [np.float64, np.float32, np.int64, np.uint64, bool]
vals = np.array([[1, 1], [5, 2], [3, 0]])
msk = np.array([[False, False], [True, False], [False, False]])

c_axis0 = 0
c_axisNone = 0
for opname in ops:
    op = getattr(nanops, opname)
    for dt in dtypes:
        v = vals.astype(dt)
        try:
            r = np.asarray(op(v, mask=msk, skipna=False, axis=0))
            if nanflag(r[0]):
                c_axis0 += 1
        except Exception:
            pass
        try:
            r = op(v, mask=msk, skipna=False, axis=None)
            if nanflag(r):
                c_axisNone += 1
        except Exception:
            pass

grid = np.arange(25, dtype=np.float64).reshape(5, 5)
gm = np.zeros((5, 5), dtype=bool)
gm[0, 0] = True

c_g0 = 0
c_g1 = 0
for opname in ops:
    op = getattr(nanops, opname)
    try:
        r = np.asarray(op(grid, mask=gm, skipna=False, axis=0))
        if nanflag(r[0]):
            c_g0 += 1
    except Exception:
        pass
    try:
        r = np.asarray(op(grid, mask=gm, skipna=False, axis=1))
        if nanflag(r[0]):
            c_g1 += 1
    except Exception:
        pass

probe("param_grid_axis0_masked_nan_count", float(c_axis0))
probe("param_grid_axisNone_masked_nan_count", float(c_axisNone))
probe("param_grid_grid_axis0_masked_nan_count", float(c_g0))
probe("param_grid_grid_axis1_masked_nan_count", float(c_g1))

